'use strict';
const $=id=>document.getElementById(id),C=HostCore,esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
let wasConnected=false;
let connection,state,config,selected='',selectedShift=localStorage.getItem('fz_next_shift')||'PM',role='Front Host',managerAuthorized=false,seatDraft={},lastPanel='',lastAuthHash='',toastTimer,communications;
const formationLabel=k=>config?.formationNames?.[k]||k;
const manager=()=>managerAuthorized&&['Manager','Owner'].includes(role),shiftBoard=()=>state?.shifts[selectedShift],party=()=>state&&C.partyFor(state,selected),currentRow=p=>state?.shifts[p?.shift||selectedShift]?.rows.find(r=>r.id===p?.rowId);
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',6500);}
function notice(text,kind=''){$('notice').textContent=text;$('notice').className=kind;}
function openDialog(title,html){if($('modal').open)$('modal').close();$('modal').classList.toggle('reservations-dialog',title==='Reservations');$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').showModal();}
function closeDialog(){$('modal').close();$('seatWizard').close();}
function requireManager(){if(manager())return true;toast('Manager / Owner authorization is required. Choose your role at the top.');return false;}
function pane(name){closeTable();if(name==='board')requestAnimationFrame(positionFrontiers);if(name==='floor')requestAnimationFrame(fitFloor);document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('active',p.id===name));document.querySelectorAll('[data-pane]').forEach(b=>b.classList.toggle('active',b.dataset.pane===name));}
function rowOptions(value='',all=false){return '<option value="">Choose server…</option>'+C.list(shiftBoard()?.rows).filter(r=>all||!r.cut).map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.server)} · ${esc(r.section)}${r.cut?' · CUT':''}</option>`).join('');}
function secondaryChoices(checked=[],own=''){const groups=new Map();for(const t of config.tables.filter(t=>t.id!==own&&(state.tables[t.id].status==='ready'||checked.includes(t.id))).sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}))){const category=/^Bar\b/i.test(t.id)?'BAR':t.id.match(/^[A-Za-z]+/)[0].toUpperCase();if(!groups.has(category))groups.set(category,[]);groups.get(category).push(t);}return '<div class="secondary-categories">'+[...groups].sort(([a],[b])=>a==='BAR'?1:b==='BAR'?-1:a.localeCompare(b)).map(([category,tables])=>`<fieldset class="secondary-category"><legend>${esc(category)}</legend><div class="secondary-grid">${tables.map(t=>`<label class="secondary-choice"><input type="checkbox" name="secondary" value="${esc(t.id)}" ${checked.includes(t.id)?'checked':''}>${esc(t.id)}</label>`).join('')}</div></fieldset>`).join('')+'</div>';}

function checkedSecondary(root=document){return [...root.querySelectorAll('input[name=secondary]:checked')].map(x=>x.value);}
function partyValues(p=party()){return p?{table:selected,partyId:p.id,partyVersion:p.version||1}: {table:selected};}
async function send(type,values={},options={}){if(!connection)throw Error('Database is not ready.');if(connection.busy){toast('One action is still waiting for confirmation.');return null;}const cmd=connection.command(type,{shift:selectedShift,...values});notice(type.replace(/_/g,' ')+' · waiting for database confirmation…','saving');try{const result=await connection.run(cmd);$('lastSaved').textContent='Confirmed · '+(result.elapsed/1000).toFixed(2)+'s';notice('LIVE · Board and Floor confirmed.');if(!options.keepDialog)closeDialog();lastPanel='';render();toast(options.message||'SAVED');return result;}catch(e){notice(e.message,'error');toast(e.message);throw e;}}
function tableOwner(id){const b=shiftBoard(),row=b?.rows.find(r=>r.id===b.assignments[id]);if(!row)return {row:null,section:''};const names=String(row.section).split(' / ');const section=Object.entries(config.formations[b.formation]||{}).find(([sec,ids])=>names.includes(sec)&&C.list(ids).includes(id))?.[0]||row.section;return {row,section};}
function renderMap(){if(!config||!state)return;const map=$('map');if(!map.querySelector('.table'))for(const t of config.tables){const button=document.createElement('button');button.className='table';button.dataset.table=t.id;button.style.cssText=`left:${t.x}%;top:${Math.min(t.y,94)}%;width:${t.w}%;height:${Math.max(5,t.h)}%;transform:translate(-50%,-50%) rotate(${t.r||0}deg)`;button.onclick=()=>{if(selected!==t.id){seatDraft={};lastPanel='';}selected=t.id;renderMap();renderPanel();if(state.tables[t.id].status==='ready'&&!C.partyFor(state,t.id)){openSeatWizard({table:t.id,rowId:shiftBoard()?.assignments[t.id]||'',step:1});return;}if(!$('tableDialog').open)$('tableDialog').showModal();};map.appendChild(button);}for(const button of map.querySelectorAll('.table')){const id=button.dataset.table,t=state.tables[id],p=C.partyFor(state,id),owner=tableOwner(id),r=p?currentRow(p):owner.row,secondary=!!p&&p.primary!==id;button.className='table '+t.status+(selected===id?' selected':'')+(secondary?' secondary':'');button.dataset.section=owner.section;button.dataset.server=owner.row?.server||'';button.setAttribute('aria-pressed',String(selected===id));button.setAttribute('aria-label',id+' '+t.status+' · Section '+(owner.section||'unassigned')+' · '+(owner.row?.server||'No server')+' · Beeper '+(owner.row?.beeper||'none')+(p?' · Seated with '+r?.server:''));button.title=id+' · Section '+(owner.section||'—')+' · '+(owner.row?.server||'UNASSIGNED');button.innerHTML='<strong>'+esc(id+(owner.section?'-'+owner.section:''))+'</strong><small>'+esc(secondary?'2ND · '+p.primary:p&&r?.id!==owner.row?.id?r?.server||'':'')+'</small>';}
 let layer=$('sectionLabels');if(!layer){layer=document.createElement('div');layer.id='sectionLabels';map.parentElement.appendChild(layer);}const groups=new Map();for(const t of config.tables){const o=tableOwner(t.id);if(!o.row)continue;const key=o.section+'|'+o.row.id;if(!groups.has(key))groups.set(key,{...o,tables:[]});groups.get(key).tables.push(t);}layer.setAttribute('aria-label','Sections, servers and beepers');layer.innerHTML=[...groups.values()].sort((a,b)=>a.section==='BAR'?1:b.section==='BAR'?-1:a.section.localeCompare(b.section,undefined,{numeric:true})).map(o=>`<div class="section-marker ${o.section==='BAR'?'bar-marker':''}" data-section-label="${esc(o.section)}"><span class="section-number">${esc(o.section==='BAR'?'BAR':'S'+o.section)}</span><strong class="section-server">${esc(o.row.cut?'CUT · '+o.row.server:o.row.server)}</strong><span class="section-beeper">BEEPER ${esc(o.row.beeper||'—')}</span></div>`).join('')||'<div class="section-empty">Choose Formation &amp; Servers to assign tables.</div>';requestAnimationFrame(fitFloor);$('floorFormation').textContent=shiftBoard()?.formation?formationLabel(shiftBoard().formation):'NO FORMATION · CHOOSE FORMATION & SERVERS';}
function fitFloor(){const map=$('map');if(!map||!$('floor').classList.contains('active'))return;const width=map.clientWidth,height=map.clientHeight;if(!width||!height)return;const compact=width<600;for(const button of map.querySelectorAll('.table')){const t=config?.tables.find(t=>t.id===button.dataset.table);if(!t)continue;const section=button.dataset.section||'',p=C.partyFor(state,t.id),secondary=!!p&&p.primary!==t.id;const label=compact?/^Bar /i.test(t.id)?t.id.replace(/^Bar /i,''):t.id:/^Bar /i.test(t.id)?t.id.replace(' ',''):t.id+(section?'-'+section:'');const detail=secondary?'2ND · '+p.primary:compact&&/^Bar /i.test(t.id)?'BAR':compact&&section?'S'+section:/^Bar /i.test(t.id)?section:'';button.querySelector('strong').textContent=label;button.querySelector('small').textContent=detail;const bw=width*t.w/100,bh=height*Math.max(5,t.h)/100;button.style.setProperty('--table-font',Math.max(5,Math.min(28,(bw-4)/(Math.max(2,label.length)*.62),(bh-3)*(detail ? 0.48 : 0.7)))+'px');button.style.setProperty('--table-small-font',Math.max(4,Math.min(12,(bw-3)/(Math.max(3,detail.length)*.6),bh*.24))+'px');}}
function renderFrontiers(){const rows=C.list(shiftBoard()?.rows).filter(r=>!r.cut),box=$('boardRows');box.querySelectorAll('.frontier-guide').forEach(x=>x.remove());if(!rows.length)return;const min=Math.min(...rows.map(C.slots)),max=Math.max(...rows.map(C.slots));for(const [kind,count]of [['min',min],['max',max]]){const line=document.createElement('div');line.className='frontier-guide '+kind;line.dataset.turn=String(count+1);line.dataset.count=String(count);line.innerHTML='<span>'+kind.toUpperCase()+'<b>'+(count+1)+'</b></span>';box.appendChild(line);}requestAnimationFrame(positionFrontiers);}
function positionFrontiers(){const box=$('boardRows'),strip=box.querySelector('.turns');if(!strip)return;const b=box.getBoundingClientRect(),s=strip.getBoundingClientRect();for(const line of box.querySelectorAll('.frontier-guide')){const index=Number(line.dataset.count)%15;line.style.left=(s.left-b.left+index*s.width/15)+'px';}}
function renderPanel(){if(!state||!config||!selected)return;const t=state.tables[selected],p=party(),signature=selected+'|'+JSON.stringify(t)+'|'+JSON.stringify(p)+'|'+C.list(shiftBoard()?.rows).map(r=>[r.id,r.server,r.cut].join(':')).join(',');if(signature===lastPanel)return;lastPanel=signature;let html=`<div class="table-title"><strong>${esc(selected)}</strong><span class="pill ${esc(t.status)}">${esc(t.status.toUpperCase())} · ${esc((p?currentRow(p):tableOwner(selected).row)?.server||'UNASSIGNED')}</span></div>`;
 if(p){const r=currentRow(p);html+=`<div class="panel-info"><b>${esc(r?.server)}</b> · ${p.people} guests<br>Main table <b>${esc(p.primary)}</b><br>Secondary <b>${esc(C.list(p.secondary).join(', ')||'None')}</b><br>${esc(p.shift)} · ${esc(r?.section||'')} · Beeper ${esc(r?.beeper||'—')}</div><div class="actions"><button id="readyAction">READY</button><button id="cleanAction">CLEAN</button></div><div class="actions"><button id="moveAction">MOVE / CHANGE</button><button id="resetBoardAction" class="danger">RESET · REMOVE BOARD</button></div><button id="advancedToggle" class="full" aria-expanded="true">ADVANCED</button><div id="advancedActions" class="advanced-actions"><button id="peopleAction">EDIT PEOPLE</button><button id="deleteAction" class="danger">DELETE PARTY · REMOVE BOARD</button><button id="secondaryAction">EDIT SECONDARY</button></div>`;}
 else if(t.status==='cleaning')html+='<p class="panel-info">Table is being cleaned.</p><button id="readyAction" class="primary full">MARK READY</button>';
 else{const assigned=shiftBoard()?.assignments[selected]||'';html+=`<button id="openSeatWizard" class="primary full">SEAT</button><button id="tableReservation" class="full">RESERVATION</button><details class="direct-seat"><summary>MANUAL ASSIGN</summary><form id="seatForm"><label for="seatPeople">Guests</label><input class="field" id="seatPeople" type="number" min="1" max="120" required value="${seatDraft.people||2}"><label for="seatServer">Server</label><select class="field" id="seatServer" required>${rowOptions(seatDraft.rowId||assigned)}</select><label>Secondary tables · optional</label>${secondaryChoices(seatDraft.secondary||[],selected)}<button type="submit" class="primary full" id="seatSubmit">SUBMIT · SEAT PARTY</button></form></details>`;const undo=Object.values(state.undo).filter(u=>C.members(u.party).includes(selected)).sort((a,b)=>b.at-a.at)[0];if(undo)html+=`<button id="undoTableAction" class="full">UNDO DELETE · ${esc(undo.party.primary)}</button>`;}
 $('tablePanel').innerHTML=html;if($('openSeatWizard'))$('openSeatWizard').onclick=()=>openSeatWizard({table:selected,rowId:shiftBoard()?.assignments[selected]||''});
 if($('tableReservation'))$('tableReservation').onclick=()=>{closeTable();operation('reservations');};
 if($('readyAction'))$('readyAction').onclick=()=>send('STATUS',{...partyValues(p),status:'ready'},{message:'Party tables READY · rotation count retained'}).catch(()=>{});
 if($('cleanAction'))$('cleanAction').onclick=()=>send('STATUS',{...partyValues(p),status:'cleaning'},{message:'Party tables marked CLEANING'}).catch(()=>{});
 if($('deleteAction')){const removeParty=()=>{const frozen=partyValues(p);if(confirm('DELETE PARTY '+C.members(p).join(' + ')+'?\n\nRemove its Board entry and make every linked table READY.'))void send('DELETE',frozen,{message:'PARTY REMOVED · ALL LINKED TABLES READY'}).catch(()=>{});};$('deleteAction').onclick=removeParty;$('resetBoardAction').onclick=removeParty;$('advancedToggle').onclick=()=>{const expanded=$('advancedActions').hidden;$('advancedActions').hidden=!expanded;$('advancedToggle').setAttribute('aria-expanded',String(expanded));};}
 if($('peopleAction'))$('peopleAction').onclick=()=>{const n=prompt('Guests for '+p.primary+' (1–120)',String(p.people));if(n!==null)void send('PEOPLE',{...partyValues(p),people:Number(n)},{message:'PEOPLE UPDATED · BOARD SLOTS REARRANGED'}).catch(()=>{});};
 if($('secondaryAction'))$('secondaryAction').onclick=()=>openPartyEdit(p,false);
 if($('moveAction'))$('moveAction').onclick=()=>openPartyEdit(p,true);
 if($('seatForm')){$('seatForm').oninput=()=>{seatDraft={people:$('seatPeople').value,rowId:$('seatServer').value,secondary:checkedSecondary($('seatForm'))};};$('seatForm').onsubmit=async e=>{e.preventDefault();const rowId=$('seatServer').value,people=Number($('seatPeople').value),warnings=C.risk(state,selectedShift,rowId,connection.now());if(warnings.length&&!confirm('RECENT PARTY WARNING\n\n'+warnings.map(x=>x.table+' · '+x.people+' guests').join('\n')+'\n\nSeat this party anyway?'))return;try{await send('SEAT',{table:selected,rowId,people,secondary:checkedSecondary($('seatForm')),confirmedRiskIds:warnings.map(x=>x.id)},{message:'PARTY SEATED · BOARD + FLOOR CONFIRMED'});seatDraft={};}catch(_){};};}
 if($('undoTableAction'))$('undoTableAction').onclick=()=>{const u=Object.values(state.undo).filter(u=>C.members(u.party).includes(selected)).sort((a,b)=>b.at-a.at)[0];if(u)void send('UNDO',{undoId:u.id},{message:'PARTY + SECONDARY + BOARD RESTORED'}).catch(()=>{});};
}
let wizard=null;
function closeTable(){if($('tableDialog')?.open)$('tableDialog').close();}
function finishRole(){render();$('roleGate').hidden=true;sessionStorage.setItem('fz_next_entered','1');pane('board');}
function initClassic(){
 window.addEventListener('resize',positionFrontiers);window.addEventListener('resize',fitFloor);window.visualViewport?.addEventListener('resize',fitFloor);if(typeof ResizeObserver!=='undefined')new ResizeObserver(fitFloor).observe($('map'));$('tableClose').onclick=closeTable;$('tableCancel').onclick=closeTable;$('wizardClose').onclick=()=>$('seatWizard').close();
 $('shiftBadge').onclick=()=>{$('shift').value=selectedShift==='PM'?'AM':'PM';$('shift').dispatchEvent(new Event('change'));};
 const showRoles=()=>{$('roleGate').hidden=false;};$('logout').onclick=()=>{managerAuthorized=false;role='Front Host';$('role').value=role;sessionStorage.removeItem('fz_next_entered');showRoles();};$('changeRole').onclick=showRoles;
 $('roleGate').hidden=!!sessionStorage.getItem('fz_next_entered');document.querySelectorAll('[data-entry-role]').forEach(b=>b.onclick=()=>{if(b.dataset.entryRole!=='Front Host'&&(!state||!config))return toast('Wait until the database is ready.');void changeRole(b.dataset.entryRole);});
}
function openSeatWizard(values={}){if(!state||!config||!connection?.connected)return toast('Wait until LIVE before seating.');closeTable();wizard={step:0,table:'',rowId:'',people:2,secondary:[],...values};drawWizard();if(!$('seatWizard').open)$('seatWizard').showModal();}
function drawWizard(){const w=wizard;if(!w)return;const titles=['Choose Table','Choose People','Choose Server & Submit'];$('wizardStep').textContent='STEP '+(w.step+1)+' OF 3';$('wizardTitle').textContent=titles[w.step];document.querySelectorAll('.wizard-bars i').forEach((b,i)=>b.className=i<=w.step?'active':'');$('wizardNext').textContent=w.step===2?'SUBMIT':'NEXT';$('wizardBack').textContent=w.step===0?'CANCEL':'PREVIOUS';let html='';
 if(w.step===0){html='<div class="classic-pick-grid">'+config.tables.map(t=>`<button data-pick-table="${esc(t.id)}" class="pick-btn ${w.table===t.id?'selected':''} ${state.tables[t.id].status}" ${state.tables[t.id].status!=='ready'?'disabled':''}>${esc(t.id)}</button>`).join('')+'</div>';}
 if(w.step===1){html='<p class="wizard-caption">PARTY SIZE · ROTATION = PEOPLE ÷ 4, ROUNDED UP</p><div class="people-pick-grid">'+Array.from({length:20},(_,i)=>`<button class="pick-btn ${w.people===i+1?'selected':''}" data-people="${i+1}">${i+1}</button>`).join('')+`</div><label for="wizardPeople">Number of guests</label><input id="wizardPeople" class="field" type="number" min="1" max="120" value="${w.people}"><div class="secondary-box"><b>Secondary tables · optional</b>${secondaryChoices(w.secondary,w.table)}</div>`;}
 if(w.step===2){html='<label for="serverSearch" class="sr-only">Search server name</label><input id="serverSearch" class="field" placeholder="Search server name…"><p class="wizard-caption">3 NAMES PER ROW · FORMATION SERVERS</p><div class="wizard-server-grid">'+C.list(shiftBoard()?.rows).filter(r=>!r.cut).map(r=>`<button class="pick-btn server-pick ${r.id===w.rowId?'selected':''}" data-server="${esc(r.id)}"><strong>${esc(r.server)}</strong><small>Section ${esc(r.section)} · Beeper ${esc(r.beeper||'—')}</small></button>`).join('')+'</div>'+`<div class="review"><div><span>TABLE</span><b>${esc(w.table)}</b></div><div><span>GUESTS</span><b>${w.people}</b></div><div><span>SECONDARY</span><b>${esc(w.secondary.join(', ')||'None')}</b></div></div>`;}
 $('wizardBody').innerHTML=html;if($('serverSearch'))$('serverSearch').oninput=()=>{$('wizardBody').querySelectorAll('[data-server]').forEach(button=>button.hidden=!button.textContent.toLowerCase().includes($('serverSearch').value.trim().toLowerCase()));};
 $('wizardBody').querySelectorAll('[data-pick-table]').forEach(b=>b.onclick=()=>{w.table=b.dataset.pickTable;if(!w.rowId)w.rowId=shiftBoard()?.assignments[w.table]||nextRow()?.id||'';w.secondary=w.secondary.filter(t=>t!==w.table);drawWizard();});
 $('wizardBody').querySelectorAll('[data-people]').forEach(b=>b.onclick=()=>{w.people=Number(b.dataset.people);drawWizard();});if($('wizardPeople'))$('wizardPeople').oninput=()=>{w.people=Number($('wizardPeople').value);};
 $('wizardBody').querySelectorAll('input[name=secondary]').forEach(b=>b.onchange=()=>{w.secondary=checkedSecondary($('wizardBody'));});$('wizardBody').querySelectorAll('[data-server]').forEach(b=>b.onclick=()=>{w.rowId=b.dataset.server;drawWizard();});
 $('wizardBack').onclick=()=>{if(w.step===0)$('seatWizard').close();else{w.step--;drawWizard();}};
 $('wizardNext').disabled=connection.busy||!connection.connected;
 $('wizardNext').onclick=async()=>{if(connection.busy)return;if(!w.table)return toast('Choose a READY table.');if(w.step===0){w.step=1;return drawWizard();}if(!Number.isInteger(w.people)||w.people<1||w.people>120)return toast('Enter 1–120 guests.');if(w.step===1){w.step=2;return drawWizard();}if(!w.rowId)return toast('Choose a server.');const warnings=C.risk(state,selectedShift,w.rowId,connection.now());if(warnings.length&&!confirm('RECENT PARTY WARNING\n\n'+warnings.map(x=>x.table+' · '+x.people+' guests').join('\n')+'\n\nSeat this party anyway?'))return;try{selected=w.table;seatDraft={};lastPanel='';await send('SEAT',{table:w.table,rowId:w.rowId,people:w.people,secondary:w.secondary,confirmedRiskIds:warnings.map(x=>x.id)},{message:'PARTY SEATED · BOARD + FLOOR CONFIRMED'});wizard=null;}catch(_){};};
}

function nextRow(){return C.list(shiftBoard()?.rows).filter(r=>!r.cut&&C.slots(r)<60).sort((a,b)=>C.slots(a)-C.slots(b))[0]||null;}
function renderBoard(){const b=shiftBoard();if(!b)return;const next=nextRow(),active=b.rows.filter(r=>!r.cut);$('nextName').textContent=next?.server||'—';$('nextMeta').textContent=next?'SECTION '+next.section+' · '+next.entries.filter(e=>e.kind==='party').length+' TABLES · BEEPER '+(next.beeper||'—'):'Set a formation to begin';const available=next?config.tables.filter(t=>b.assignments[t.id]===next.id&&state.tables[t.id].status==='ready'):[];$('nextReady').textContent=next?'READY TABLES · '+available.length+' AVAILABLE · '+(available.map(t=>t.id).join(' · ')||'None'):'';$('seatNext').disabled=!next||!connection?.connected||connection.busy;$('seatNext').onclick=()=>openSeatWizard({rowId:next?.id||''});$('teamCount').textContent=active.length+' active';
 $('boardRows').innerHTML=b.rows.length?b.rows.map(r=>{const cells=r.entries.flatMap(e=>e.kind==='party'?[`<button class="turn party" data-party-table="${esc(e.primary)}" title="${esc(e.primary)} · ${e.people} guests"><b>${esc(e.primary)}</b><small>${e.people} guests</small></button>`,...Array.from({length:Math.ceil(e.people/4)-1},()=>'<div class="turn continuation">↳</div>')]:[`<button class="turn ${e.kind}" ${e.kind==='manual'?`data-unskip="${esc(e.id)}" data-row="${esc(r.id)}"`:''} title="${e.kind==='auto'?'BAR AUTO':'MANUAL'} SKIP"><b>SKIP</b></button>`]);const used=cells.length,shown=Math.max(45,Math.ceil(used/15)*15);while(cells.length<shown)cells.push(`<div class="turn empty ${cells.length===used?'current':''}" aria-label="Empty turn ${cells.length+1}"></div>`);return `<article class="board-row ${r.cut?'cut':''} ${r===next?'next':''}"><div class="row-meta"><span class="section-bubble">${esc(r.section==='BAR'?'BAR':'S'+r.section)}</span><div><strong>${esc(r.server)}</strong><small>${r.entries.filter(e=>e.kind==='party').length} tables · ${used} turns${r.cut?' · CUT':''}</small><span class="beeper-chip">BEEPER ${esc(r.beeper||'—')}</span></div></div><div class="turns">${cells.join('')}</div><div class="row-actions"><button class="row-seat" data-row-seat="${esc(r.id)}" ${r.cut?'disabled':''}>SEAT</button><button class="row-skip" data-skip="${esc(r.id)}">SKIP</button><button class="row-floor" data-row-floor="${esc(r.id)}">FLOOR</button>${selectedShift==='PM'&&String(r.section).toUpperCase().includes('BAR')?`<button class="bar-toggle ${r.barAuto!==false?'on':'off'}" data-bar-toggle="${esc(r.id)}" data-bar-next="${r.barAuto===false}" aria-pressed="${r.barAuto!==false}">AUTO SKIP ${r.barAuto!==false?'ON':'OFF'}</button>`:''}</div></article>`;}).join(''):'<div class="empty-state"><h3>Start this shift.</h3><p>Choose Formation &amp; Servers to load the rotation.</p><button class="primary" data-op="setup">FORMATION &amp; SERVERS</button></div>';
 $('boardRows').querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>{const answer=prompt('How many skips? (1–60)','1');if(answer===null)return;const count=Number(answer);if(!Number.isInteger(count)||count<1||count>60)return toast('Enter 1–60 skips.');void send('SKIP',{rowId:b.dataset.skip,count},{message:count+' MANUAL SKIP'+(count===1?'':'S')+' ADDED'}).catch(()=>{});});$('boardRows').querySelectorAll('[data-unskip]').forEach(b=>b.onclick=()=>{if(requireManager())void send('SKIP',{rowId:b.dataset.row,entryId:b.dataset.unskip},{message:'MANUAL SKIP REMOVED'}).catch(()=>{});});$('boardRows').querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operation(b.dataset.op));$('boardRows').querySelectorAll('[data-bar-toggle]').forEach(b=>b.onclick=()=>send('ROW_EDIT',{rowId:b.dataset.barToggle,barAuto:b.dataset.barNext==='true'},{message:'BAR AUTO SKIP '+(b.dataset.barNext==='true'?'ON':'OFF')}).catch(()=>{}));$('boardRows').querySelectorAll('[data-row-seat]').forEach(b=>b.onclick=()=>openSeatWizard({rowId:b.dataset.rowSeat}));$('boardRows').querySelectorAll('[data-row-floor]').forEach(b=>b.onclick=()=>pane('floor'));$('boardRows').querySelectorAll('[data-party-table]').forEach(b=>b.onclick=()=>{pane('floor');$('map').querySelector('[data-table="'+b.dataset.partyTable+'"]').click();});}
function render(){if(!state||!config)return;$('logout').textContent=(manager()?role.toUpperCase()+' ':'')+'LOG OUT';$('day').textContent=state.day;$('shiftBadge').textContent=selectedShift;renderMap();renderPanel();renderBoard();renderFrontiers();}
function openPartyEdit(p,moving){const frozen=partyValues(p);openDialog(moving?'Move / Change Party':'Edit Secondary',`<p class="helper">${esc(p.primary)} · ${p.people} guests · ${esc(currentRow(p)?.server)}</p>${moving?`<label for="newPrimary">Primary table</label><select id="newPrimary" class="field">${config.tables.filter(t=>state.tables[t.id].status==='ready'||C.members(p).includes(t.id)).map(t=>`<option ${t.id===p.primary?'selected':''}>${esc(t.id)}</option>`).join('')}</select><label for="newServer">Server</label><select id="newServer" class="field">${rowOptions(p.rowId)}</select>`:''}<label>Secondary tables</label><div id="secondaryOptions">${secondaryChoices(C.list(p.secondary),p.primary)}</div><button id="savePartyEdit" class="primary full">SAVE ${moving?'MOVE / CHANGE':'SECONDARY'}</button>`);
 if(moving)$('newPrimary').onchange=()=>{$('secondaryOptions').innerHTML=secondaryChoices(C.list(p.secondary).filter(id=>id!==$('newPrimary').value),$('newPrimary').value);};$('savePartyEdit').onclick=()=>send(moving?'MOVE':'SECONDARY',{...frozen,...(moving?{target:$('newPrimary').value,rowId:$('newServer').value}:{}),secondary:checkedSecondary($('modalBody'))},{message:'PARTY UPDATED · ALL LINKS CONFIRMED'}).catch(()=>{});}
const operations=[['setup','Formation & Servers','Choose formation and assign your servers.'],['join','Breaking Section','Split tables to a new server at the end of rotation.'],['beeper','Beeper','Assign and verify beepers 1–20.'],['map','Edit Table Map','Change tables inside a formation section.'],['formation','Edit Formation','Edit formation structure and current server rows.'],['correct','Correct Wrong AM / PM','Move this shift and its Floor links together.'],['roster','Add New Server','Add a new employee name to the shared server list.'],['cut','Cut / Uncut Employee','Manage active rotation employees.'],['reservations','Reservations','Create and manage upcoming reservations.'],['chat','Manager Chat / VN / Call','Messages, voice notes and live calls.'],['shout','Team Shout Out','Send a large announcement to connected devices.'],['password','Edit Manager Password','Update the shared manager gate.'],['bar','Repair BAR · Auto SKIP','Convert matching manual skips to automatic skips.'],['undo','Undo Delete','Restore a deleted party and its secondary tables.'],['pending','Recheck Pending Operation','Resolve a save whose connection was interrupted.'],['clear','Clear All Board + Floor','Reset both shifts, Floor, skips and Undo.']];
function operation(name){if(!state||!config)return toast('Wait until the database is ready.');$('seatWizard').close();if(['map','formation','correct','cut','shout','password','bar','clear','roster'].includes(name)&&!requireManager())return;
 if(name==='roster')return rosterDialog();if(name==='setup')return setupDialog();if(name==='join')return joinDialog();if(name==='beeper')return beeperDialog();if(name==='cut')return cutDialog();if(name==='map')return mapDialog();if(name==='formation')return formationDialog();if(name==='reservations')return reservationDialog();if(name==='chat')return communications.openChat();
 if(name==='correct'){if(confirm('Correct '+selectedShift+' to '+(selectedShift==='AM'?'PM':'AM')+'?\n\nThe other shift must be empty. Party and secondary links move together.'))void send('CORRECT',{}, {message:'SHIFT CORRECTED'}).then(r=>{if(r){selectedShift=selectedShift==='AM'?'PM':'AM';$('shift').value=selectedShift;lastPanel='';render();}}).catch(()=>{});return;}
 if(name==='clear'){if(confirm('CLEAR ALL BOARD + FLOOR?\n\nBoth shifts, Floor parties and Undo are removed. Templates, employee list, reservations and communications remain.'))void send('CLEAR',{}, {message:'ALL BOARD + FLOOR CLEARED'}).catch(()=>{});return;}
 if(name==='undo'){const records=Object.values(state.undo).sort((a,b)=>b.at-a.at);openDialog('Undo Delete',records.map(u=>`<button class="full" data-undo="${esc(u.id)}">RESTORE ${esc(C.members(u.party).join(' + '))} · ${u.party.people} guests · ${esc(u.shift)}</button>`).join('')||'<p class="helper">No Delete to undo today.</p>');$('modalBody').querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>send('UNDO',{undoId:b.dataset.undo},{message:'PARTY + BOARD RESTORED'}).catch(()=>{}));return;}
 if(name==='pending'){notice('Rechecking the same operation ID…','saving');void connection.recoverPending().then(()=>{notice('Pending operation resolved.');toast('Operation rechecked.');}).catch(e=>{notice(e.message,'error');toast(e.message);});return;}
 if(name==='bar'){openDialog('Repair BAR Manual → Auto SKIP',`<p class="helper">Matching manual SKIPs after each two BAR parties become automatic. Other manual SKIPs stay.</p><select id="barRow" class="field">${rowOptions('',true)}</select><button class="primary full" id="barRepair">REPAIR PM BAR</button>`);$('barRepair').onclick=()=>send('BAR_REPAIR',{rowId:$('barRow').value},{message:'BAR AUTO SKIP REPAIRED'}).catch(()=>{});return;}
 if(name==='shout'){openDialog('Team Shout Out','<label for="shoutText">Message</label><textarea id="shoutText" class="field" maxlength="400"></textarea><button id="sendShout" class="primary full">SEND TO CONNECTED HOSTS</button>');$('sendShout').onclick=async()=>{try{const text=$('shoutText').value.trim();if(!text)return;await connection.ref.child('shout').set({id:HostCore.uid(),text,at:connection.now(),expiresAt:connection.now()+120000,from:role});closeDialog();toast('SHOUT SENT');}catch(e){toast(e.message);}};return;}
 if(name==='password')return passwordDialog();}
async function addServerName(value){const name=C.canonical(value);if(!name||name.length>100)throw Error('Enter a server name, up to 100 characters.');await connection.updateConfig(c=>{c.servers=C.list(c.servers);if(!c.servers.some(s=>s.toLowerCase()===name.toLowerCase()))c.servers.push(name);return c;});return name;}
function rosterDialog(){openDialog('Add New Server','<label for="newServerName">New server name</label><input id="newServerName" class="field" maxlength="100"><button id="addServerName" class="primary full">ADD NEW SERVER</button><p class="helper">The name becomes available on all tablets in Formation & Servers and Breaking Section.</p>');$('addServerName').onclick=async()=>{try{const name=await addServerName($('newServerName').value);closeDialog();toast('SERVER ADDED · '+name);}catch(e){toast(e.message);}};}
function setupDialog(){openDialog('Formation & Servers',`<label for="setupFormation">Formation</label><select id="setupFormation" class="field">${Object.keys(config.formations).map(k=>`<option value="${esc(k)}">${esc(formationLabel(k))}</option>`).join('')}</select><div id="sectionAssignments"></div><details class="new-server-box"><summary>+ ADD NEW SERVER</summary><label for="setupNewServer">New server name</label><input id="setupNewServer" class="field" maxlength="100"><button id="setupAddServer" class="full">ADD SERVER NAME</button></details><button id="saveSetup" class="primary full">START ${selectedShift} SHIFT</button>`);const draw=()=>{$('sectionAssignments').innerHTML=Object.keys(config.formations[$('setupFormation').value]).map(sec=>`<div class="form-row"><label>SECTION ${esc(sec)}</label><select data-section="${esc(sec)}"><option value="">Choose employee…</option>${config.servers.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div>`).join('');};$('setupFormation').onchange=draw;draw();$('setupAddServer').onclick=async()=>{try{const name=await addServerName($('setupNewServer').value);if(!name)return;for(const select of $('sectionAssignments').querySelectorAll('select')){if(![...select.options].some(o=>o.value===name)){const option=document.createElement('option');option.value=name;option.textContent=name;select.appendChild(option);}}$('setupNewServer').value='';toast('SERVER ADDED · '+name);}catch(e){toast(e.message);}};$('saveSetup').onclick=()=>send('SETUP',{formation:$('setupFormation').value,servers:Object.fromEntries([...$('sectionAssignments').querySelectorAll('select')].map(s=>[s.dataset.section,s.value]))},{message:'FORMATION + SERVERS READY'}).catch(()=>{});}
function joinDialog(){openDialog('Breaking Section',`<label for="joinServer">Arriving server</label><input id="joinServer" class="field" list="employeeNames"><datalist id="employeeNames">${config.servers.map(s=>`<option value="${esc(s)}">`).join('')}</datalist><label for="joinSection">Section label</label><input id="joinSection" class="field" placeholder="e.g. 4B"><label>Transfer these table assignments</label><div class="secondary-grid">${config.tables.map(t=>`<label class="secondary-choice"><input type="checkbox" name="joinTable" value="${esc(t.id)}">${esc(t.id)}</label>`).join('')}</div><p class="helper">The new employee joins at the end of the rotation. Existing parties keep their original server.</p><button id="saveJoin" class="primary full">BREAK SECTION + ADD SERVER</button>`);$('saveJoin').onclick=()=>send('JOIN',{server:$('joinServer').value,section:$('joinSection').value,tables:[...$('modalBody').querySelectorAll('[name=joinTable]:checked')].map(x=>x.value)},{message:'SECTION SPLIT · SERVER ADDED TO ROTATION END'}).catch(()=>{});}
function beeperDialog(){openDialog('Beeper',C.list(shiftBoard()?.rows).map(r=>`<div class="form-row"><label>${esc(r.server)}</label><select data-beeper="${esc(r.id)}"><option value="">No beeper</option>${Array.from({length:20},(_,i)=>`<option value="${i+1}" ${String(i+1)===r.beeper?'selected':''}>${i+1}</option>`).join('')}</select></div>`).join('')||'<p>Set Formation & Servers first.</p>');$('modalBody').querySelectorAll('[data-beeper]').forEach(e=>e.onchange=()=>send('BEEPER',{rowId:e.dataset.beeper,beeper:e.value},{keepDialog:true,message:'BEEPER CONFIRMED'}).catch(()=>{}));}
function cutDialog(){openDialog('Cut / Uncut Employee',C.list(shiftBoard()?.rows).map(r=>`<div class="form-row"><label>${esc(r.server)} · ${esc(r.section)}</label><button data-cut="${esc(r.id)}" data-value="${r.cut?'false':'true'}" class="${r.cut?'primary':''}">${r.cut?'UNCUT':'CUT EMPLOYEE'}</button></div>`).join('')||'<p>No employees in this shift.</p>');$('modalBody').querySelectorAll('[data-cut]').forEach(b=>b.onclick=()=>send('CUT',{rowId:b.dataset.cut,cut:b.dataset.value==='true'},{keepDialog:true,message:'EMPLOYEE STATUS CONFIRMED'}).then(cutDialog).catch(()=>{}));}
function formationDialog(){openDialog('Edit Formation',`<p class="helper">Edit current rows. Table membership is edited in Edit Table Map.</p>${C.list(shiftBoard()?.rows).map(r=>`<div class="form-row"><label>${esc(r.server)}</label><div><input data-row-server="${esc(r.id)}" class="field" value="${esc(r.server)}"><input data-row-section="${esc(r.id)}" class="field" value="${esc(r.section)}" aria-label="Section label"><button data-save-row="${esc(r.id)}" class="full">SAVE ROW</button></div></div>`).join('')}<label for="addEmployee">Add employee to roster</label><input id="addEmployee" class="field"><button id="saveEmployee" class="full">ADD EMPLOYEE</button><button id="editTemplate" class="primary full">EDIT / CREATE FORMATION TEMPLATE</button>`);$('modalBody').querySelectorAll('[data-save-row]').forEach(b=>b.onclick=()=>{const id=b.dataset.saveRow;void send('ROW_EDIT',{rowId:id,server:$('modalBody').querySelector('[data-row-server="'+id+'"]').value,section:$('modalBody').querySelector('[data-row-section="'+id+'"]').value},{keepDialog:true,message:'FORMATION ROW SAVED'}).catch(()=>{});});$('saveEmployee').onclick=async()=>{const name=C.canonical($('addEmployee').value);if(!name)return;try{await connection.updateConfig(c=>{if(!c.servers.includes(name))c.servers.push(name);return c;});toast('EMPLOYEE ADDED');$('addEmployee').value='';}catch(e){toast(e.message);}};$('editTemplate').onclick=mapDialog;}
function mapDialog(){openDialog('Edit Table Map / Formation Template',`<label for="mapTemplate">Template</label><select id="mapTemplate" class="field">${Object.keys(config.formations).map(k=>`<option value="${esc(k)}">${esc(formationLabel(k))}</option>`).join('')}</select><label for="templateName">Name</label><input id="templateName" class="field"><label for="mapText">One section per line · SECTION: table, table</label><textarea id="mapText" class="field" rows="12"></textarea><p class="helper">Example: 1: A1, A2, A3. Each table can occur once. Saving a new name creates a formation.</p><button id="saveTemplate" class="primary full">SAVE TEMPLATE + CURRENT ASSIGNMENTS</button>`);const draw=()=>{const name=$('mapTemplate').value;$('templateName').value=formationLabel(name);$('mapText').value=Object.entries(config.formations[name]).map(([sec,tables])=>sec+': '+tables.join(', ')).join('\n');};$('mapTemplate').onchange=draw;draw();$('saveTemplate').onclick=async()=>{try{const old=$('mapTemplate').value,label=$('templateName').value.trim(),name=label.replace(/[.#$\[\]\/]/g,'_');if(!name)throw Error('Enter a formation name.');const form={},seen=new Set();for(const line of $('mapText').value.split('\n').filter(x=>x.trim())){const pos=line.indexOf(':');if(pos<1)throw Error('Use SECTION: table, table');const sec=line.slice(0,pos).trim().replace(/[.#$\[\]\/]/g,'_'),ids=line.slice(pos+1).split(',').map(x=>x.trim()).filter(Boolean);if(form[sec])throw Error('Duplicate section '+sec);for(const id of ids){if(!state.tables[id])throw Error('Unknown table '+id);if(seen.has(id))throw Error('Duplicate table '+id);seen.add(id);}form[sec]=ids;}if(!Object.keys(form).length)throw Error('Add at least one section.');await connection.updateConfig(c=>{c.formations[name]=form;c.formationNames=c.formationNames||{};c.formationNames[name]=label;return c;});if(shiftBoard().formation===old){const mapping={};for(const [sec,ids]of Object.entries(form)){const r=shiftBoard().rows.find(r=>r.section.split(' / ').includes(sec));if(r)ids.forEach(id=>mapping[id]=r.id);}await send('ASSIGNMENTS',{mapping},{keepDialog:true,message:'MAP + CURRENT ASSIGNMENTS SAVED'});}closeDialog();toast('FORMATION TEMPLATE SAVED');}catch(e){toast(e.message);}};}
async function verifyPassword(value){const auth=config.managerAuth;if(!auth)throw Error('Manager access is not configured.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(auth.salt.match(/../g).map(x=>parseInt(x,16))),iterations:auth.iterations,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')===auth.hash;}
function passwordDialog(){openDialog('Edit Manager Password','<label for="oldPassword">Current manager password</label><input type="password" id="oldPassword" autocomplete="current-password" class="field"><label for="newPassword">New password · at least 8 characters</label><input type="password" id="newPassword" autocomplete="new-password" class="field"><label for="confirmPassword">Confirm new password</label><input type="password" id="confirmPassword" autocomplete="new-password" class="field"><button id="savePassword" class="primary full">UPDATE SHARED PASSWORD</button>');$('savePassword').onclick=async()=>{try{if(!await verifyPassword($('oldPassword').value))throw Error('Current password does not match.');const value=$('newPassword').value;if(value.length<8||value!==$('confirmPassword').value)throw Error('Use matching passwords with at least 8 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),key=await crypto.subtle.importKey('raw',new TextEncoder().encode(value),'PBKDF2',false,['deriveBits']),iterations=150000,bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},key,256),hex=a=>[...new Uint8Array(a)].map(x=>x.toString(16).padStart(2,'0')).join('');await connection.updateConfig(c=>{c.managerAuth={salt:hex(salt),iterations,hash:hex(bits)};return c;});managerAuthorized=false;role='Front Host';$('role').value=role;closeDialog();toast('PASSWORD UPDATED · SIGN IN AGAIN');}catch(e){toast(e.message);}};}
function reservationDialog(){communications.openReservations();}
async function createManagerGate(value){openDialog('First Manager Setup','<p class="helper">Create a new shared manager password for this app. The old app password is not copied.</p><form id="firstPasswordForm"><label for="firstPassword">New manager password · at least 8 characters</label><input id="firstPassword" type="password" autocomplete="new-password" class="field" required><label for="firstPasswordConfirm">Confirm password</label><input id="firstPasswordConfirm" type="password" autocomplete="new-password" class="field" required><button class="primary full">CREATE MANAGER ACCESS</button></form>');$('firstPasswordForm').onsubmit=async event=>{event.preventDefault();try{const password=$('firstPassword').value;if(password.length<8||password!==$('firstPasswordConfirm').value)throw Error('Use matching passwords with at least 8 characters.');const salt=crypto.getRandomValues(new Uint8Array(16)),iterations=150000,key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},key,256),hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join(''),auth={salt:hex(salt),iterations,hash:hex(bits)};await connection.updateConfig(c=>{if(c.managerAuth)return undefined;c.managerAuth=auth;return c;});managerAuthorized=true;role=value;$('role').value=value;closeDialog();communications.publishPresence();finishRole();toast('MANAGER ACCESS CREATED');}catch(e){toast(e.message);}};}
async function changeRole(value){if(['Manager','Owner'].includes(value)){if(!config.managerAuth){$('role').value=role;return createManagerGate(value);}openDialog(value+' Access','<form id="roleForm"><label for="managerPassword">Manager password</label><input id="managerPassword" type="password" autocomplete="current-password" class="field" required><button class="primary full" type="submit">ENTER '+esc(value.toUpperCase())+'</button></form>');$('roleForm').onsubmit=async e=>{e.preventDefault();try{if(!await verifyPassword($('managerPassword').value))throw Error('Password does not match.');managerAuthorized=true;role=value;$('role').value=role;closeDialog();communications?.publishPresence();finishRole();toast(value+' ready');}catch(e){toast(e.message);}};$('role').value=role;}else{managerAuthorized=false;role=value;$('role').value=role;communications?.publishPresence();finishRole();}}
async function checkDay(){if(!state||!connection?.connected||connection.busy)return;if(C.dayAt(connection.now())>state.day)try{await send('DAILY_RESET',{}, {message:'NEW DAY · BOARD + FLOOR READY'});}catch(_){};}
async function boot(){initClassic();document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>pane(b.dataset.pane));$('modalClose').onclick=closeDialog;$('shift').value=selectedShift;$('shift').onchange=()=>{selectedShift=$('shift').value;localStorage.setItem('fz_next_shift',selectedShift);seatDraft={};lastPanel='';render();};$('role').onchange=()=>changeRole($('role').value);const menuGroups=[['SHIFT & SECTIONS',['setup','join','beeper','map','formation','correct']],['STAFF',['roster','cut']],['DATA & COMMUNICATION',['reservations','chat','shout','password','bar','undo','pending','clear']]];$('operations').innerHTML=menuGroups.map(([title,ids])=>'<section class="menu-group"><div class="menu-group-title">'+title+'</div><div class="menu-grid">'+operations.filter(([id])=>ids.includes(id)).map(([id,title,desc])=>`<button class="op-card ${id==='clear'?'danger':''}" data-op="${id}"><strong>${title}</strong><small>${desc}</small></button>`).join('')+'</div></section>').join('');document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>operation(b.dataset.op));$('chatOpen').onclick=()=>communications?.openChat();
 const options=await fetch('./app-config.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('App configuration missing.');return r.json();});connection=new HostConnection(options);
 connection.onConfig=c=>{if(lastAuthHash&&lastAuthHash!==c.managerAuth?.hash){managerAuthorized=false;role='Front Host';$('role').value=role;}lastAuthHash=c.managerAuth?.hash||'';config=c;render();};connection.onState=s=>{state=s;render();};connection.onStatus=status=>{if(status.connected&&!wasConnected)communications?.publishPresence();wasConnected=!!status.connected;$('connection').className='connection '+(status.connected&&status.ready?'live':'offline');$('connection').textContent=status.connected&&status.ready?'LIVE':'OFFLINE / CONNECTING';document.querySelectorAll('#tablePanel button,#seatForm select,#seatForm input,#wizardNext,#seatNext,[data-row-seat],[data-skip],[data-bar-toggle]').forEach(b=>b.disabled=status.busy||!status.connected||!status.ready||!!(b.dataset.rowSeat&&shiftBoard()?.rows.find(r=>r.id===b.dataset.rowSeat)?.cut));if(status.error)notice(status.error,'error');else if(status.busy)notice('SAVING · waiting for the database…','saving');else if(status.connected&&status.ready)notice('LIVE · ready for host operations.');else notice('Connection not ready. Saves are blocked until LIVE.','error');};connection.start();communications=new HostCommunications({connection,getRole:()=>role,isManager:manager,openDialog,closeDialog,toast,escape:esc});communications.start();setInterval(checkDay,15000);window.addEventListener('online',checkDay);setTimeout(checkDay,2000);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
